"// hooks/strings.ts",
"var STRINGS = { en: EN, \"zh-TW\": ZH_TW, \"zh-CN\": ZH_CN };",
"var agentLabel = (agent, s) => {",
"  if (agent === \"\")",
"    return \"\";",
"  const key = Object.hasOwn(s.agentNames, agent) ? agent : agent.toLowerCase();",
"  return Object.hasOwn(s.agentNames, key) ? s.agentNames[key] ?? agent : agent;",
"};",
"var plainReason = (s, code) => /^(EACCES|EPERM|EROFS)$/.test(code) ? s.storageReadOnly : /^(EBUSY|EAGAIN)$/.test(code) ? s.storageBusy : code === \"ENOSPC\" ? s.storageFull : code === \"EISDIR\" ? s.storageIsFolder : /^(ENOENT|ENOTDIR)$/.test(code) ? s.storageMissing : s.storageUnknown;",
"var plainReadReason = (s, code) => /^(EACCES|EPERM|EROFS)$/.test(code) ? s.storageUnreadable : /^(EBUSY|EAGAIN)$/.test(code) ? s.storageBusy : code === \"ENOSPC\" ? s.storageFull : code === \"EISDIR\" ? s.storageIsFolder : /^(ENOENT|ENOTDIR)$/.test(code) ? s.storageMissing : s.storageUnknown;",
"var langOf = (value) => {",
"  if (typeof value !== \"string\")",
"    return null;",
"  const text = value.trim().toLowerCase();",
"  if (text === \"\")",
"    return null;",
"  const exact = LANGS.find((one) => one.toLowerCase() === text);",
"  if (exact !== undefined)",
"    return exact;",
"  if (/(zh[-_]?(tw|hk|mo|hant))|繁|traditional|taiwan|台灣|臺灣|香港/.test(text))",
"    return \"zh-TW\";",
"  if (/(zh[-_]?(cn|sg|hans))|简|simplified|chinese|中文|^zh\\b/.test(text))",
"    return \"zh-CN\";",
"  if (/^en(?:\\b|_)|english|英文|英語|英语/.test(text))",
"    return \"en\";",
"  return null;",
"};",
